<script setup>
import { update as wayfinderUpdate1, destroy as wayfinderDestroy2, store as wayfinderStore4 } from './../../../actions/App/Http/Controllers/Staff/AdminStoryController';
import { stories as wayfinderStories3 } from './../../../actions/App/Http/Controllers/PublicController';

import { Link, router, useForm } from '@inertiajs/vue3';
import { reactive } from 'vue';
import StaffAdminLayout from '../../../Layouts/StaffAdminLayout.vue';

const props = defineProps({ stories: Object, courses: Array });
const editors = reactive(Object.fromEntries(props.stories.data.map((story) => [story.id, {
  name: story.name, slug: story.slug, course_id: story.course_id || '', role: story.role, cohort: story.cohort || '', outcome: story.outcome,
  quote: story.quote, story: story.story, color: story.color, status: story.status,
}])));
const create = useForm({ name: '', slug: '', course_id: '', role: '', cohort: '', outcome: '', quote: '', story: '', color: 'lilac', status: 'draft' });
function save(id) { router.put(wayfinderUpdate1.url({ story: id }), editors[id], { preserveScroll: true }); }
function remove(item) { if (window.confirm(`Remove ${item.name}'s story from the public website?`)) router.delete(wayfinderDestroy2.url({ story: item.id })); }
</script>

<template><StaffAdminLayout><div class="admin-heading"><div><div class="eyebrow">PUBLIC STORIES</div><h1>Learner stories.</h1><p>Manage the outcomes and testimonials that help prospective learners see what a program can make possible.</p></div><Link :href="wayfinderStories3().url" target="_blank" class="button button-dark">View public stories <UiIcon name="arrow-up-right" :size="13"/></Link></div>
  <section class="admin-panel"><h2>Add a story</h2><form class="admin-form" @submit.prevent="create.post(wayfinderStore4().url)"><div class="admin-form-grid"><label>Learner name<input v-model="create.name" required></label><label>URL slug <small>(leave blank to generate)</small><input v-model="create.slug"></label></div><div class="admin-form-grid"><label>Course<select v-model="create.course_id"><option value="">No course linked</option><option v-for="course in courses" :key="course.id" :value="course.id">{{ course.title }}</option></select></label><label>Role or next step<input v-model="create.role" required placeholder="Product designer at ..."></label></div><div class="admin-form-grid"><label>Cohort<input v-model="create.cohort" placeholder="Cohort 24"></label><label>Outcome headline<input v-model="create.outcome" required placeholder="Built and shared a portfolio project"></label></div><label>Quote<textarea v-model="create.quote" rows="2" required maxlength="1500"></textarea></label><label>Full story<textarea v-model="create.story" rows="5" required maxlength="12000"></textarea></label><div class="admin-form-grid"><label>Accent style<select v-model="create.color"><option value="lilac">Lilac</option><option value="blue">Blue</option><option value="orange">Orange</option></select></label><label>Status<select v-model="create.status"><option value="draft">Draft</option><option value="published">Published</option></select></label></div><div class="admin-form-actions"><button class="button button-dark" :disabled="create.processing">Create story</button></div></form></section>
  <section v-for="item in stories.data" :key="item.id" class="admin-panel story-editor"><div class="story-editor-head"><div><span class="admin-chip" :class="`status-${item.status}`">{{ item.status }}</span><h2>{{ item.name }}</h2><small>{{ item.course?.title || 'No course linked' }} · {{ item.slug }}</small></div><button class="admin-danger" @click="remove(item)">Delete</button></div><form class="admin-form" @submit.prevent="save(item.id)"><div class="admin-form-grid"><label>Name<input v-model="editors[item.id].name"></label><label>Slug<input v-model="editors[item.id].slug"></label></div><div class="admin-form-grid"><label>Course<select v-model="editors[item.id].course_id"><option value="">No course linked</option><option v-for="course in courses" :key="course.id" :value="course.id">{{ course.title }}</option></select></label><label>Role<input v-model="editors[item.id].role"></label></div><div class="admin-form-grid"><label>Cohort<input v-model="editors[item.id].cohort"></label><label>Outcome<input v-model="editors[item.id].outcome"></label></div><label>Quote<textarea v-model="editors[item.id].quote" rows="2"></textarea></label><label>Story<textarea v-model="editors[item.id].story" rows="4"></textarea></label><div class="admin-form-grid"><label>Accent style<select v-model="editors[item.id].color"><option value="lilac">Lilac</option><option value="blue">Blue</option><option value="orange">Orange</option></select></label><label>Status<select v-model="editors[item.id].status"><option value="draft">Draft</option><option value="published">Published</option></select></label></div><div class="admin-form-actions"><button class="button button-dark">Save story</button></div></form></section>
<div v-if="!stories.data.length" class="admin-empty">No learner stories have been created yet.</div><div v-if="stories.last_page > 1" class="admin-pagination"><span>Page {{ stories.current_page }} of {{ stories.last_page }} · {{ stories.total }} stories</span><div><Link v-if="stories.prev_page_url" :href="stories.prev_page_url">Previous</Link><Link v-if="stories.next_page_url" :href="stories.next_page_url">Next</Link></div></div></StaffAdminLayout></template>

<style scoped>.story-editor{margin-top:16px}.story-editor-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.story-editor-head h2{margin:9px 0 5px}.story-editor-head small{color:var(--academy-muted)}.admin-danger{border:0;background:transparent;color:var(--academy-danger);font-size:11px;cursor:pointer}.status-published{background:var(--academy-success-surface);color:var(--academy-success)}.status-draft{background:var(--academy-warning-surface);color:var(--academy-warning)}</style>
